algorithms.pseudocode:
FullBasis(X, cl):
  B ← ∅
  for each S ⊆ X:
    for each x ∈ cl(S) \ S:
      B ← B ∪ {(S, x)}
  return B

Complexity: O(2^|X| · |X| · T_cl)

ForwardChain(B, A):
  C ← A
  repeat:
    for each (S, x) ∈ B:
      if S ⊆ C and x ∉ C:
        C ← C ∪ {x}
  until no change
  return C

Complexity: O(|X| · |B|)

PrimeSpectrum(X, cl):
  closed ← {A ⊆ X | cl(A) = A}
  primes ← ∅
  for each P ∈ closed:
    if P ≠ X and IsMeetPrime(P, closed):
      primes ← primes ∪ {P}
  return primes

Complexity: O(2^|X| · T_cl + |closed|³ · |X|)
